<?php foreach($documents as$item):?><article class="profile-doc-row"><div><strong><?= $escape($documentTypeNames[(string)$item['category']]??(string)$item['title']) ?></strong><small><?= $escape((string)$item['original_name']) ?> · v<?= (int)$item['version_number'] ?> · <?= $date($item['created_at'],true) ?></small><?php if(!empty($item['description'])):?><small>Obs.: <?= $escape((string)$item['description']) ?></small><?php endif;?></div><div class="profile-doc-actions"><?php if(str_starts_with((string)$item['mime_type'],'image/')||(string)$item['mime_type']==='application/pdf'):?><a class="button-secondary button-small" target="_blank" href="<?= $escape($basePath) ?>/students/<?= $studentId ?>/documents/<?= (int)$item['id'] ?>/download?inline=1" title="Visualizar"><i class="fa-solid fa-eye"></i></a><?php endif;?><a class="button-secondary button-small" href="<?= $escape($basePath) ?>/students/<?= $studentId ?>/documents/<?= (int)$item['id'] ?>/download" title="Baixar"><i class="fa-solid fa-download"></i></a><?php if($canManage):?><form method="post" action="<?= $escape($basePath) ?>/students/<?= $studentId ?>/documents/<?= (int)$item['id'] ?>/delete" onsubmit="return confirm('Arquivar este documento? O arquivo será preservado para auditoria.')"><?= $csrfField ?><input type="hidden" name="confirm_delete" value="1"><button class="button-danger button-small" type="submit" title="Arquivar"><i class="fa-solid fa-box-archive"></i></button></form><?php endif;?></div></article><?php endforeach;?><?php endif;?></div></div></div></section>
